    return data ? '<img src="' + data.replace(/"/g, "&quot;") + '">' : "";
}

function sqDecorateContent(content, bookId, chapterId, chapterTitle) {
    var cfg = sqCommentConfig.call(this);
    var sourceRef = sqSource.call(this);
    var titleKey = "sq_title_bubble_" + String(chapterId || "");
    function saveTitle(value) {
        try { if (sourceRef && sourceRef.put && chapterId) sourceRef.put(titleKey, String(value || "")); } catch(e) {}
    }
    if ((!cfg.paragraph && !cfg.chapter) || !bookId || !chapterId) {
        saveTitle("");
        return content;
    }

    var response = sqRenderExt.call(this, bookId, chapterId);
    var paragraphs = sqParagraphList(response);
    if (!paragraphs.length) {
        saveTitle("");
        return content;
    }

    var titleItem = null;
    var bodyItems = [];
    for (var p = 0; p < paragraphs.length; p++) {
        var item = paragraphs[p] || {};
        var order = Number(item.orderId !== undefined ? item.orderId : item.OrderId);
        var count = Number(item.commentCount || item.CommentCount || 0);
        if (count <= 0) continue;
        if (order === 0) titleItem = item;
        else if (order > 0) bodyItems.push(item);
    }

    if (cfg.chapter && titleItem) {
        var titleCount = Number(titleItem.commentCount || titleItem.CommentCount || 0);
        var titlePid = titleItem.paragraphId || titleItem.ParagraphId || "p000";
        var titleText = String(titleItem.text || titleItem.Text || titleItem.summaryText || titleItem.SummaryText || chapterTitle || "");
        saveTitle(sqBubbleData.call(this, titleCount, bookId, chapterId, titlePid, !!(titleItem.isHotParagraph || titleItem.IsHotParagraph), "chapter", titleText));
    } else {
        saveTitle("");
    }
    if (!cfg.paragraph) return content;

    var pieces = String(content || "").split(/(<br\s*\/?>)/i);
    var textIndexes = [];
    for (var i = 0; i < pieces.length; i++) {
        if (!/^<br\s*\/?>$/i.test(pieces[i]) && String(pieces[i]).trim()) textIndexes.push(i);
    }
    for (var b = 0; b < bodyItems.length; b++) {
        var bodyItem = bodyItems[b] || {};
        var bodyOrder = Number(bodyItem.orderId !== undefined ? bodyItem.orderId : bodyItem.OrderId);
        var bodyCount = Number(bodyItem.commentCount || bodyItem.CommentCount || 0);
        var bodyPid = bodyItem.paragraphId || bodyItem.ParagraphId || ("p" + String(bodyOrder));
        var target = textIndexes[bodyOrder - 1];
        if (target !== undefined) {
            var bodyText = String(bodyItem.text || bodyItem.Text || bodyItem.summaryText || bodyItem.SummaryText || pieces[target] || "");
            pieces[target] += sqBubbleImage.call(this, bodyCount, bookId, chapterId, bodyPid, !!(bodyItem.isHotParagraph || bodyItem.IsHotParagraph), bodyText);
        }
    }
    return pieces.join("");
}

function sqEscapeHtml(value) {
    return String(value == null ? "" : value)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

function sqRichText(comment) {
    var raw = String(comment && (comment.richText || comment.text) || "");
    var images = [];
    raw = raw.replace(/<img\b[^>]*>/gi, function(tag) {
        var match = tag.match(/src=["'](data:image\/(?:webp|png|gif);base64,[A-Za-z0-9+/=]+)["']/i);
        if (!match) return "";
        var token = "__SQ_EMOJI_" + images.length + "__";
        images.push('<img class="emoji" src="' + match[1] + '" alt="">');
        return token;
    });
    raw = sqEscapeHtml(raw).replace(/\r?\n/g, "<br>");
    for (var i = 0; i < images.length; i++) raw = raw.replace("__SQ_EMOJI_" + i + "__", images[i]);
    return raw;
}

function sqFormatTime(value) {
    var time = Number(value || 0);
    if (!time) return "";
    try { return sqJava.call(this).timeFormatUTC(time, "yyyy-MM-dd HH:mm", 28800000); } catch(e) { return ""; }
}

function sqReplyHtml(reply) {
