    for (var i = 0; i < replies.length; i++) replyHtml += sqReplyHtml(replies[i]);
    var badges = comment.isAuthor ? '<span class="badge">作者</span>' : "";
    if (comment.fanCard && comment.fanCard.levelName) badges += '<span class="badge muted">' + sqEscapeHtml(comment.fanCard.levelName) + '</span>';

    var replyNum = Number(comment.replyNum || 0);
    var nextIndex = replyData.nextItemIndex;
    var hasMore = replyNum > replies.length && nextIndex !== null && nextIndex !== undefined && String(nextIndex) !== "";
    var safeMid = String(comment.mid || "comment").replace(/[^A-Za-z0-9_-]/g, "_");
    var replyTarget = "sq_replies_" + safeMid + "_" + (_sqReplyDomSeq++);
    var moreButton = hasMore
        ? '<button class="reply-more" type="button" data-target="' + replyTarget + '" data-mid="' + sqEscapeHtml(comment.mid || "") + '" data-cursor="' + sqEscapeHtml(nextIndex) + '" data-author="' + sqEscapeHtml(comment.authorId || "0") + '" onclick="sqLoadReplies(this)">展开更多回复</button>'
        : "";

